#!/usr/bin/env python3
"""Writes the generated part of u32/PROOF.bend: everything after the line

  # ---- generated by gen/proof.py from here on: do not edit by hand ----

The part above it is written by hand. Run: python3 u32/gen/proof.py

The generated proofs are: the Nat library (the semiring laws, the order as
witnesses, unique quotients, sums that do not wrap); the value of a product
(Word.mul is shift and add); U32 division (Base's U32.divmod.go, one
quotient bit a step); the bitwise operations as values; and U32 shifts by k
bits. Ring identities are written by scripts/natproof.py.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "..", "..", "scripts"))
import natproof as N  # noqa: E402
from natproof import P, Pf, calc, cast, chain, hyp, ring, rewrite, sym, trans  # noqa: E402

N.CFG["law"] = "Laws."
N.OUT.prefix = "ur.r"
OUTF = os.path.join(HERE, "..", "PROOF.bend")
MARK = "# ---- generated by gen/proof.py from here on: do not edit by hand ----"

out = []
_flushed = [0]


def put(s=""):
    # ring defs made while building s go first
    defs = N.OUT.defs[_flushed[0]:]
    if defs:
        out.append("\n".join(defs))
        _flushed[0] = len(N.OUT.defs)
    out.append(s)


def V(n, w):
    return f"Word.to_nat({n}, {w})"


def eqty(a, b, t="Nat"):
    return "{" + f"{P(a) if t == 'Nat' else a} == {P(b) if t == 'Nat' else b} : {t}" + "}"


def btrue(e):
    return "{" + f"{e} == True{{}} : Bool" + "}"


def bcong(var, body, a, b, e):
    """Equal.cong into Bool."""
    return f"Equal.cong(Nat, Bool, {var} => {body}, {P(a)}, {P(b)}, {e})"


def btrans(a, b, c, ab, bc):
    return f"Equal.trans(Bool, {a}, {b}, {c}, {ab}, {bc})"


def bsym(a, b, e):
    return f"Equal.sym(Bool, {a}, {b}, {e})"


def le_from(x, y, w, pf):
    """{is_le(x, y) == True} from w and pf : add(w, x) == y."""
    x, y = P(x), P(y)
    s = N.add(P(w), x)
    assert pf.lhs == s and pf.rhs == y, (pf, s, y)
    # is_le(x, y) == is_le(x, add(w, x)) == True
    return btrans(f"Nat.is_le({x}, {y})", f"Nat.is_le({x}, {s})", "True{}",
                  bsym(f"Nat.is_le({x}, {s})", f"Nat.is_le({x}, {y})", bcong("zz", f"Nat.is_le({x}, zz)", s, y, pf.text)),
                  f"Laws.nat_le_add({x}, {P(w)})")


def lt_from(x, y, w, pf):
    """{is_lt(x, y) == True} from w and pf : add(w, 1n+x) == y."""
    x, y = P(x), P(y)
    s = N.add(P(w), N.succ(x))
    assert pf.lhs == s and pf.rhs == y, (pf, s, y)
    return btrans(f"Nat.is_lt({x}, {y})", f"Nat.is_lt({x}, {s})", "True{}",
                  bsym(f"Nat.is_lt({x}, {s})", f"Nat.is_lt({x}, {y})", bcong("zz", f"Nat.is_lt({x}, zz)", s, y, pf.text)),
                  f"Laws.nat_lt_add({x}, {P(w)})")


def absurd(ty, w, x, pf):
    """Empty.absurd(ty, ...) from pf : add(w, 1n+x) == x."""
    w, x = P(w), P(x)
    assert pf.lhs == N.add(w, N.succ(x)) and pf.rhs == x, pf
    return f"Empty.absurd({ty}, Laws.nat_succ_add_absurd({w}, {x}, {pf.text}))"


