    kargs_f = f"32n, {Sv}, {Bv}, {Rv}, {Av}, {Sv}, T, {Lb}, False{{}}, eput, {eL}, {eg_f}, {er1_f.text}, un.bit_le(a0), i2, Laws.word_value_lt(32n, bw)"
