def extra():
    put("# More of the Nat library\n")
    od = "U.U32Nat.odd(Nat.double(x))"
    hd = "U.U32Nat.half(Nat.double(x))"
    pf = calc(f"Nat.add({od}, Nat.double({low('k', hd)}))",
              (f"Nat.add(0n, Nat.double({low('k', hd)}))", hyp("un.odd_d(x)", od, "0n")),
              (f"Nat.add(0n, Nat.double({low('k', 'x')}))", hyp("Laws.half_double(x)", hd, "x")),
              (f"Nat.double({low('k', 'x')})", "="))
    put(f"""def Laws.low_double(k, x):
  {pf.text}

def Laws.high_double(k, x):
  {rewrite(high('k', hd), high('k', 'x'), hyp('Laws.half_double(x)', hd, 'x')).text}
""")
    Dm = D("m", "1n")
    W = f"Nat.sub({Dm}, 1n+x)"
    lo, hi = low("k", "x"), high("k", "x")
    Dj = D("j", "1n")
    pf = calc(f"Nat.add(Nat.add({W}, {lo}), 1n+{D('k', hi)})",
              (f"Nat.add({W}, 1n+Nat.add({lo}, {D('k', hi)}))", "ring"),
              (f"Nat.add({W}, 1n+x)", law("low_high", f"Nat.add({lo}, {D('k', hi)})", "x", "k", "x")),
              (Dm, hyp(f"Laws.nat_lt_witness(x, {Dm}, h)", f"Nat.add({W}, 1n+x)", Dm)),
              (D("Nat.add(k, j)", "1n"), sym(hyp("e", "Nat.add(k, j)", "m"))),
              (D("k", Dj), sym(law("dbl_dbl", D("k", Dj), D("Nat.add(k, j)", "1n"), "k", "j", "1n"))))
    lt1 = lt_from(D("k", hi), D("k", Dj), f"Nat.add({W}, {lo})", pf)
    put(f"""def Laws.high_lt(k, j, m, x, e, h):
  Equal.trans(Bool, Nat.is_lt({hi}, {Dj}), Nat.is_lt({D('k', hi)}, {D('k', Dj)}), True{{}}, Equal.sym(Bool, Nat.is_lt({D('k', hi)}, {D('k', Dj)}), Nat.is_lt({hi}, {Dj}), Laws.dbl_lt(k, {hi}, {Dj})), {lt1})
""")
    wa, wb = "Nat.sub(c, 1n+a)", "Nat.sub(d, 1n+b)"
    W = f"Nat.add(Nat.mul({wa}, Nat.add({wb}, 1n+b)), Nat.add({wb}, Nat.add(b, Nat.add(Nat.mul(a, {wb}), a))))"
    pf = calc(f"Nat.add({W}, 1n+Nat.mul(a, b))",
              (f"Nat.mul(Nat.add({wa}, 1n+a), Nat.add({wb}, 1n+b))", "ring"),
              (f"Nat.mul(c, Nat.add({wb}, 1n+b))", hyp("Laws.nat_lt_witness(a, c, h1)", f"Nat.add({wa}, 1n+a)", "c")),
              ("Nat.mul(c, d)", hyp("Laws.nat_lt_witness(b, d, h2)", f"Nat.add({wb}, 1n+b)", "d")))
    put(f"""def Laws.nat_mul_lt(a, b, c, d, h1, h2):
  {lt_from('Nat.mul(a, b)', 'Nat.mul(c, d)', W, pf)}

def Laws.nat_le_dbl(k, x):
  match k:
    case 0n:
      Laws.nat_le_refl(x)
    case 1n+ +j:
      un.le_trans(x, {D('j', 'x')}, Nat.double({D('j', 'x')}), Laws.nat_le_dbl(j, x), un.le_double({D('j', 'x')}))
""")
    K = "Nat.sub(k, j)"
    eq = calc(D(K, D("j", "x")),
              (D(f"Nat.add({K}, j)", "x"), law("dbl_dbl", D(K, D("j", "x")), D(f"Nat.add({K}, j)", "x"), K, "j", "x")),
              (D("k", "x"), hyp("Laws.nat_le_witness(j, k, h)", f"Nat.add({K}, j)", "k")))
    A = D("j", "x")
    put(f"""def Laws.dbl_le_exp(j, k, x, h):
  Equal.trans(Bool, Nat.is_le({A}, {D('k', 'x')}), Nat.is_le({A}, {D(K, A)}), True{{}}, Equal.sym(Bool, Nat.is_le({A}, {D(K, A)}), Nat.is_le({A}, {D('k', 'x')}), Equal.cong(Nat, Bool, zz => Nat.is_le({A}, zz), {D(K, A)}, {D('k', 'x')}, {eq.text})), Laws.nat_le_dbl({K}, {A}))
""")
    X = "Nat.add(a, Nat.double(r))"
    put(f"""def Laws.divstep_value(n, s, b, r, a, r1, t, l, g, e, el, eg, er, ha, hr, hb):
  ud.p1(Nat.add(r1, Nat.mul(U.U32Nat.bit(g), b)), {X}, r1, b, ud.k(n, s, b, r, a, r1, t, l, g, e, el, eg, er, ha, hr, hb))

def Laws.divstep_lt(n, s, b, r, a, r1, t, l, g, e, el, eg, er, ha, hr, hb):
  ud.p2(Nat.add(r1, Nat.mul(U.U32Nat.bit(g), b)), {X}, r1, b, ud.k(n, s, b, r, a, r1, t, l, g, e, el, eg, er, ha, hr, hb))
""")

